insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('8ed76313-95b5-46e4-87f2-fdbbc56ad686', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Writerly Practice, Attention, and Creative Discipline', 'The course begins by treating writing as a repeatable artistic practice: students learn how to observe, draft, keep notebooks, build habits, tolerate uncertainty, and turn attention into material.', 0),
  ('1ebeda14-e63f-4099-94fb-7254e7717481', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '8ed76313-95b5-46e4-87f2-fdbbc56ad686', 'subtopic'::public.curated_course_node_type, 'Writing as a Sustained Practice', 'Students learn that creative work depends on rhythms, rituals, deadlines, and revision habits as much as inspiration.', 0),
  ('49e3a5c3-1d0e-476e-a36b-97b33cc71351', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '1ebeda14-e63f-4099-94fb-7254e7717481', 'concept'::public.curated_course_node_type, 'Daily and weekly writing routines', null, 0),
  ('9c3536fe-5387-4095-b7ae-c1eed3dd77a4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '1ebeda14-e63f-4099-94fb-7254e7717481', 'concept'::public.curated_course_node_type, 'Generative prompts and constraints', null, 1),
  ('d1bfbaba-d439-4283-b91f-9d28c93c7f5c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '1ebeda14-e63f-4099-94fb-7254e7717481', 'concept'::public.curated_course_node_type, 'Process logs, drafts, and reflection', null, 2),
  ('45957ea3-0c48-4d39-8e39-06fbb9be3e87', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '8ed76313-95b5-46e4-87f2-fdbbc56ad686', 'subtopic'::public.curated_course_node_type, 'Attention and Observation', 'The point is to sharpen perception so students can gather precise sensory, social, emotional, and linguistic material.', 1),
  ('0259059c-bf97-4edc-9683-0e98259676ef', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '45957ea3-0c48-4d39-8e39-06fbb9be3e87', 'concept'::public.curated_course_node_type, 'Sensory noticing and concrete detail', null, 0),
  ('38d0ecd8-5e4a-40aa-ad25-97ef4b9443db', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '45957ea3-0c48-4d39-8e39-06fbb9be3e87', 'concept'::public.curated_course_node_type, 'Place, overheard speech, gesture, and atmosphere', null, 1),
  ('9d7ba083-b194-4f62-9d82-1ab9d2533f1d', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '45957ea3-0c48-4d39-8e39-06fbb9be3e87', 'concept'::public.curated_course_node_type, 'Memory, imagination, and researched observation', null, 2),
  ('4e5d670f-e237-411b-94e9-8222857e0bad', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '8ed76313-95b5-46e4-87f2-fdbbc56ad686', 'subtopic'::public.curated_course_node_type, 'Risk, Failure, and Experiment', 'Students practice making exploratory work without needing early drafts to be polished or safe.', 2),
  ('47d3d2be-1e2b-4d17-991d-d284c1492d5c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '4e5d670f-e237-411b-94e9-8222857e0bad', 'concept'::public.curated_course_node_type, 'Productive failure and false starts', null, 0),
  ('a394d25a-f8f8-44ad-95f5-c70e8c93660f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '4e5d670f-e237-411b-94e9-8222857e0bad', 'concept'::public.curated_course_node_type, 'Play, imitation, variation, and constraint', null, 1),
  ('6744dacd-b6b7-4603-92f3-814a5a2f59a7', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '4e5d670f-e237-411b-94e9-8222857e0bad', 'concept'::public.curated_course_node_type, 'Moving from exercise to project', null, 2),
  ('dfa5146f-0309-4fea-9929-9ff26b974992', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Reading Like a Writer', 'Students read published work not only for meaning, but for craft: how writers make decisions about voice, structure, pacing, image, syntax, genre, and form.', 1),
  ('be346603-8fc1-4516-b632-e5bf9b476d56', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'dfa5146f-0309-4fea-9929-9ff26b974992', 'subtopic'::public.curated_course_node_type, 'Craft-Based Annotation', 'Students learn to mark techniques that can become usable tools in their own writing.', 0),
  ('5604974a-7c2a-4936-8cbb-8dc199df1c38', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'be346603-8fc1-4516-b632-e5bf9b476d56', 'concept'::public.curated_course_node_type, 'Scene openings and endings', null, 0),
  ('f68c0539-366a-4052-9afc-97d25dc98f30', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'be346603-8fc1-4516-b632-e5bf9b476d56', 'concept'::public.curated_course_node_type, 'Sentence rhythm and syntax', null, 1),
  ('aa5c6fab-48a9-48bf-85d6-db1cf38e44bd', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'be346603-8fc1-4516-b632-e5bf9b476d56', 'concept'::public.curated_course_node_type, 'Image patterns, motifs, and turns', null, 2),
  ('556f10ce-6784-45ea-b452-02b98e036d8a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'dfa5146f-0309-4fea-9929-9ff26b974992', 'subtopic'::public.curated_course_node_type, 'Imitation and Transformation', 'Imitation teaches craft by making students inhabit another writer''s choices before transforming them into original work.', 1),
  ('3d33f74d-b14a-46cd-ac7c-d2c37df8de17', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '556f10ce-6784-45ea-b452-02b98e036d8a', 'concept'::public.curated_course_node_type, 'Style imitation exercises', null, 0),
  ('5dc633c2-cb82-40d0-bff7-17a69f465a3c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '556f10ce-6784-45ea-b452-02b98e036d8a', 'concept'::public.curated_course_node_type, 'Genre translation and point-of-view shifts', null, 1),
  ('fb58188b-b084-45f7-904e-9e6590785b52', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '556f10ce-6784-45ea-b452-02b98e036d8a', 'concept'::public.curated_course_node_type, 'Borrowing structure without copying content', null, 2),
  ('7f5eca20-5db2-4c7f-8e53-703cb15452d4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'dfa5146f-0309-4fea-9929-9ff26b974992', 'subtopic'::public.curated_course_node_type, 'Literary Lineages', 'Students connect their work to traditions, influences, and counter-traditions instead of writing in a vacuum.', 2),
  ('c34fceed-3236-48d7-9c78-792fe45d2ac4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7f5eca20-5db2-4c7f-8e53-703cb15452d4', 'concept'::public.curated_course_node_type, 'Contemporary models and classic forms', null, 0),
  ('7fb985fa-c116-497e-87fb-1e5a80cfa089', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7f5eca20-5db2-4c7f-8e53-703cb15452d4', 'concept'::public.curated_course_node_type, 'Canon expansion and diverse mentor texts', null, 1),
  ('57ddcc44-ca58-410b-ae34-a23b00dd1009', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7f5eca20-5db2-4c7f-8e53-703cb15452d4', 'concept'::public.curated_course_node_type, 'Influence maps and writer statements', null, 2),
  ('75a5f0a6-ccad-4894-95fa-6248797eff07', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Image, Voice, Scene, and Narrative Detail', 'This foundation module teaches the cross-genre elements that make writing vivid: image, voice, scene, character, description, pacing, and the felt texture of language.', 2),
  ('6f94f167-a048-4b53-9603-f5a1a59b5062', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '75a5f0a6-ccad-4894-95fa-6248797eff07', 'subtopic'::public.curated_course_node_type, 'Image and Sensory Texture', 'Students learn to write from particulars rather than abstractions, making meaning through concrete detail.', 0),
  ('aa32d29f-922e-4b12-80c0-d34c58abfae5', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6f94f167-a048-4b53-9603-f5a1a59b5062', 'concept'::public.curated_course_node_type, 'Visual, tactile, sonic, olfactory, and kinesthetic image', null, 0),
  ('e3402e4e-bb77-43fe-80da-062462a8e6d7', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6f94f167-a048-4b53-9603-f5a1a59b5062', 'concept'::public.curated_course_node_type, 'Metaphor, simile, symbol, and motif', null, 1),
  ('7b0a372f-c7a3-4474-96ed-ee605f485d5b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6f94f167-a048-4b53-9603-f5a1a59b5062', 'concept'::public.curated_course_node_type, 'Avoiding decorative or generic description', null, 2),
  ('29ad3b73-0833-486a-9062-11d9114f7215', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '75a5f0a6-ccad-4894-95fa-6248797eff07', 'subtopic'::public.curated_course_node_type, 'Voice and Persona', 'The class studies voice as stance, rhythm, diction, selection, and pressure on the page.', 1),
  ('20407f89-e1dd-4029-8681-51c4c09ce491', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '29ad3b73-0833-486a-9062-11d9114f7215', 'concept'::public.curated_course_node_type, 'Diction, register, and syntax', null, 0),
  ('a2fe489f-fdc9-4db8-bf6b-b9a68cb97f0f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '29ad3b73-0833-486a-9062-11d9114f7215', 'concept'::public.curated_course_node_type, 'Narrative authority and intimacy', null, 1),
  ('fb184e7d-116e-4794-9bce-58724d628153', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '29ad3b73-0833-486a-9062-11d9114f7215', 'concept'::public.curated_course_node_type, 'Persona, mask, and implied speaker', null, 2),
  ('8342666f-1fb7-464f-825e-d433d1b78608', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '75a5f0a6-ccad-4894-95fa-6248797eff07', 'subtopic'::public.curated_course_node_type, 'Scene Construction', 'Students practice dramatizing experience through action, dialogue, setting, and change.', 2),
  ('4e3cfa49-f36c-4f96-8e0b-8df257b39c59', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '8342666f-1fb7-464f-825e-d433d1b78608', 'concept'::public.curated_course_node_type, 'Entering late and leaving early', null, 0),
  ('cfb1c7e8-fd96-466e-a2af-6a1a6e389903', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '8342666f-1fb7-464f-825e-d433d1b78608', 'concept'::public.curated_course_node_type, 'Beats, tension, and escalation', null, 1),
  ('f8028e1d-4a0f-4208-b4d1-e4d40c98b8fc', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '8342666f-1fb7-464f-825e-d433d1b78608', 'concept'::public.curated_course_node_type, 'Scene versus summary', null, 2),
  ('4df74a4c-6773-43ac-a213-420fe22ae620', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Fiction Workshop: Character, Plot, Point of View, and World', 'Fiction workshops teach students how invented worlds become believable through desire, conflict, causality, point of view, setting, and revision.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f214b2ba-2843-4212-bc60-d0c16dac9cc3', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '4df74a4c-6773-43ac-a213-420fe22ae620', 'subtopic'::public.curated_course_node_type, 'Character and Desire', 'Students learn to build characters whose choices, contradictions, and pressures generate narrative movement.', 0),
  ('ae126da9-a570-4001-974c-08581705ebc0', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f214b2ba-2843-4212-bc60-d0c16dac9cc3', 'concept'::public.curated_course_node_type, 'Want, need, wound, and misbelief', null, 0),
  ('5d3cf841-967c-4852-b56f-81fdf7a36abd', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f214b2ba-2843-4212-bc60-d0c16dac9cc3', 'concept'::public.curated_course_node_type, 'Interior life and external action', null, 1),
  ('4eb5a044-4a3a-4065-91d3-e6521709af07', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f214b2ba-2843-4212-bc60-d0c16dac9cc3', 'concept'::public.curated_course_node_type, 'Secondary characters and relational pressure', null, 2),
  ('c39f8f17-cd6e-4ebe-9d68-fd560fa3fef4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '4df74a4c-6773-43ac-a213-420fe22ae620', 'subtopic'::public.curated_course_node_type, 'Plot and Structure', 'The goal is to understand plot as change under pressure, not as a mechanical formula.', 1),
  ('44b4a0aa-b670-46d4-bfff-320b84201044', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c39f8f17-cd6e-4ebe-9d68-fd560fa3fef4', 'concept'::public.curated_course_node_type, 'Inciting incidents, reversals, and consequences', null, 0),
  ('d2f1037d-c33c-4ba6-9683-c8b84c504822', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c39f8f17-cd6e-4ebe-9d68-fd560fa3fef4', 'concept'::public.curated_course_node_type, 'Scene sequences and causality', null, 1),
  ('a58e2a0a-6002-49d5-a22d-af4dcc60484f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c39f8f17-cd6e-4ebe-9d68-fd560fa3fef4', 'concept'::public.curated_course_node_type, 'Open endings, compression, and escalation', null, 2),
  ('f725bc55-d78a-4276-ba56-d8071c6ab281', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '4df74a4c-6773-43ac-a213-420fe22ae620', 'subtopic'::public.curated_course_node_type, 'Point of View and Worldbuilding', 'Students study how narrative distance and world details shape what readers know, feel, and trust.', 2),
  ('d9736c4b-d590-4e4e-b3e6-82950de6f494', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f725bc55-d78a-4276-ba56-d8071c6ab281', 'concept'::public.curated_course_node_type, 'First, second, third, and omniscient point of view', null, 0),
  ('34ff8c53-d4bf-48a3-8afb-960244af2e8b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f725bc55-d78a-4276-ba56-d8071c6ab281', 'concept'::public.curated_course_node_type, 'Narrative reliability and focalization', null, 1),
  ('56301f5b-ed68-420f-a33a-3ef5453babae', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f725bc55-d78a-4276-ba56-d8071c6ab281', 'concept'::public.curated_course_node_type, 'Setting, social world, and speculative rules', null, 2),
  ('89e20d98-a812-4cd1-a1d6-b54cec366a85', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Poetry Workshop: Line, Sound, Image, and Form', 'Poetry gives students a concentrated laboratory for language: every line break, sound, image, silence, and formal choice changes meaning.', 4),
  ('65ac9242-8ed5-4662-a808-754c02953cbd', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '89e20d98-a812-4cd1-a1d6-b54cec366a85', 'subtopic'::public.curated_course_node_type, 'Line and Syntax', 'Students learn how lineation creates emphasis, pacing, suspense, and surprise.', 0),
  ('47a72d87-bfa6-475c-9aa4-44e95f52ffcf', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '65ac9242-8ed5-4662-a808-754c02953cbd', 'concept'::public.curated_course_node_type, 'End-stopped and enjambed lines', null, 0),
  ('e385b468-b67d-40dc-bfe8-772c1ebb3761', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '65ac9242-8ed5-4662-a808-754c02953cbd', 'concept'::public.curated_course_node_type, 'Stanza architecture and white space', null, 1),
  ('e84a7260-eca8-424e-b480-1f670f8dfc22', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '65ac9242-8ed5-4662-a808-754c02953cbd', 'concept'::public.curated_course_node_type, 'Syntax across line breaks', null, 2),
  ('2978f715-cd7f-40c8-afcc-be9a7389c461', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '89e20d98-a812-4cd1-a1d6-b54cec366a85', 'subtopic'::public.curated_course_node_type, 'Sound and Music', 'This subtopic trains the ear: poems think through rhythm, repetition, consonance, vowel music, and silence.', 1),
  ('73c6956f-17e0-4513-b081-4fcd48a2ee81', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '2978f715-cd7f-40c8-afcc-be9a7389c461', 'concept'::public.curated_course_node_type, 'Meter, cadence, and free verse rhythm', null, 0),
  ('a6db0df8-0081-41cf-a524-43fd8a753698', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '2978f715-cd7f-40c8-afcc-be9a7389c461', 'concept'::public.curated_course_node_type, 'Rhyme, slant rhyme, alliteration, and assonance', null, 1),
  ('10ca5d12-5eb4-4a6e-94ae-c91793392a8c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '2978f715-cd7f-40c8-afcc-be9a7389c461', 'concept'::public.curated_course_node_type, 'Refrain, echo, and sonic pattern', null, 2),
  ('25f6771e-9108-4148-8655-7c60995fbba9', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '89e20d98-a812-4cd1-a1d6-b54cec366a85', 'subtopic'::public.curated_course_node_type, 'Form and Experiment', 'Students use inherited and invented forms as engines for discovery rather than as decorative containers.', 2),
  ('951d8c2f-1581-4888-828c-1a81b142bd96', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '25f6771e-9108-4148-8655-7c60995fbba9', 'concept'::public.curated_course_node_type, 'Sonnet, villanelle, ghazal, ode, elegy, and prose poem', null, 0),
  ('c59fac13-02a7-45eb-9259-da985c5ed132', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '25f6771e-9108-4148-8655-7c60995fbba9', 'concept'::public.curated_course_node_type, 'Documentary, visual, and hybrid poetics', null, 1),
  ('aff0d972-1b95-46b6-9ed8-5ea678898d87', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '25f6771e-9108-4148-8655-7c60995fbba9', 'concept'::public.curated_course_node_type, 'Revision through compression and expansion', null, 2),
  ('f7e0a7c6-19cb-43ef-b2b5-e847b74e0a4b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Creative Nonfiction, Memoir, and the Personal Essay', 'Creative nonfiction asks students to shape real material ethically and artfully through scene, reflection, research, persona, memory, and structure.', 5),
  ('64b1a3f5-eb6a-4f64-b59a-7c2fcde63d77', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f7e0a7c6-19cb-43ef-b2b5-e847b74e0a4b', 'subtopic'::public.curated_course_node_type, 'Truth, Memory, and Persona', 'Students examine the responsibilities and possibilities of writing from lived experience.', 0),
  ('210c2a0d-d023-494a-8f05-1abf0f7c2422', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '64b1a3f5-eb6a-4f64-b59a-7c2fcde63d77', 'concept'::public.curated_course_node_type, 'Memory as evidence and construction', null, 0),
  ('3e859a67-7dc0-4e7b-9d58-a036f5713251', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '64b1a3f5-eb6a-4f64-b59a-7c2fcde63d77', 'concept'::public.curated_course_node_type, 'Narrator versus author', null, 1),
  ('8079d5d2-3ec8-4412-86ad-95f4267fb661', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '64b1a3f5-eb6a-4f64-b59a-7c2fcde63d77', 'concept'::public.curated_course_node_type, 'Fact, interpretation, and emotional truth', null, 2),
  ('7d5c6d0c-704e-4221-8c21-2e3e499203c2', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f7e0a7c6-19cb-43ef-b2b5-e847b74e0a4b', 'subtopic'::public.curated_course_node_type, 'Essay Structures', 'The essay becomes a thinking form: students learn to organize inquiry, scene, reflection, and digression.', 1),
  ('4a31136d-6da9-4ebc-9d08-17e8ae50dba4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7d5c6d0c-704e-4221-8c21-2e3e499203c2', 'concept'::public.curated_course_node_type, 'Braided, lyric, segmented, and hermit-crab essays', null, 0),
  ('6c247457-d872-45b7-9ec9-3aa3e88ae4b3', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7d5c6d0c-704e-4221-8c21-2e3e499203c2', 'concept'::public.curated_course_node_type, 'Scene-reflection balance', null, 1),
  ('ea50becf-9d13-46e0-bd24-d1689bcb9346', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7d5c6d0c-704e-4221-8c21-2e3e499203c2', 'concept'::public.curated_course_node_type, 'Open questions and intellectual movement', null, 2),
  ('69d9c08d-6538-4c98-bdb5-8daac95d19d6', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f7e0a7c6-19cb-43ef-b2b5-e847b74e0a4b', 'subtopic'::public.curated_course_node_type, 'Research in Creative Nonfiction', 'Research can deepen nonfiction without flattening it into a report.', 2),
  ('daea3980-3604-488e-9c76-39be8359f286', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '69d9c08d-6538-4c98-bdb5-8daac95d19d6', 'concept'::public.curated_course_node_type, 'Interview, archive, and field notes', null, 0),
  ('caf21465-468b-46e1-a161-2e3546b0a78f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '69d9c08d-6538-4c98-bdb5-8daac95d19d6', 'concept'::public.curated_course_node_type, 'Citation, attribution, and fair use habits', null, 1),
  ('b4190152-e387-470c-bb05-3e175a985e70', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '69d9c08d-6538-4c98-bdb5-8daac95d19d6', 'concept'::public.curated_course_node_type, 'Ethics of writing about family, community, and harm', null, 2),
  ('5c1f5cb1-4867-41f7-aa78-3acab397a6ea', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Dialogue, Playwriting, and Dramatic Action', 'Writing for the stage teaches conflict, embodiment, compression, subtext, voice, and the power of what is unsaid.', 6),
  ('c6d7094d-126a-45c2-b96d-633cc02089b4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '5c1f5cb1-4867-41f7-aa78-3acab397a6ea', 'subtopic'::public.curated_course_node_type, 'Dramatic Conflict', 'Students learn that plays move through action, need, obstacle, pressure, and changing relationships.', 0);
