values
  ('b935083e-9271-4fe7-99eb-dbab40da3d40', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c6d7094d-126a-45c2-b96d-633cc02089b4', 'concept'::public.curated_course_node_type, 'Objective, tactic, obstacle, and stakes', null, 0),
