  ('f4793465-c90a-4753-817a-a3e7cdf64508', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c6d7094d-126a-45c2-b96d-633cc02089b4', 'concept'::public.curated_course_node_type, 'Turning points and reversals', null, 2),
  ('f218f507-ca04-4da7-87e7-cae2e370549b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '5c1f5cb1-4867-41f7-aa78-3acab397a6ea', 'subtopic'::public.curated_course_node_type, 'Dialogue and Subtext', 'Dialogue is studied as action, evasion, rhythm, status, and desire rather than information exchange.', 1),
  ('95f09807-33fb-4126-9fe6-c3039e4ea4a8', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f218f507-ca04-4da7-87e7-cae2e370549b', 'concept'::public.curated_course_node_type, 'Subtext and silence', null, 0),
  ('9def422d-2879-4dd7-90a9-097546becf92', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f218f507-ca04-4da7-87e7-cae2e370549b', 'concept'::public.curated_course_node_type, 'Status shifts and interruption', null, 1),
  ('93610288-937e-40c5-9c2f-d0c67492a7a5', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f218f507-ca04-4da7-87e7-cae2e370549b', 'concept'::public.curated_course_node_type, 'Distinct voices and compression', null, 2),
  ('be5840c5-5d32-405e-96a1-b464084ea869', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '5c1f5cb1-4867-41f7-aa78-3acab397a6ea', 'subtopic'::public.curated_course_node_type, 'Theatrical Form', 'Students think about scripts as blueprints for performance.', 2),
  ('8a5c2259-2af4-45a7-9cd7-6bed2fb9b80c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'be5840c5-5d32-405e-96a1-b464084ea869', 'concept'::public.curated_course_node_type, 'Stage directions and playable action', null, 0),
  ('94fbc816-7209-49e1-867a-6e3ec99fd1ff', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'be5840c5-5d32-405e-96a1-b464084ea869', 'concept'::public.curated_course_node_type, 'Ten-minute play and one-act structures', null, 1),
  ('95f4d0cb-4484-497f-937a-ff59fd9de344', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'be5840c5-5d32-405e-96a1-b464084ea869', 'concept'::public.curated_course_node_type, 'Staged reading, feedback, and rewrite', null, 2),
  ('c27dd226-a151-451a-b2fb-10922b68f915', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Screenwriting, Visual Story, and Adaptation', 'Screenwriting trains students to tell stories through images, scenes, structure, pacing, and industry-readable formats.', 7),
  ('e6eaf9ee-30da-45f3-9e60-a4d21f74cc73', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c27dd226-a151-451a-b2fb-10922b68f915', 'subtopic'::public.curated_course_node_type, 'Screenplay Format and Visual Writing', 'Students learn how screenwriting conventions serve clarity, timing, and production imagination.', 0),
  ('240f9b89-76be-4e87-bbef-a47beb9edc91', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'e6eaf9ee-30da-45f3-9e60-a4d21f74cc73', 'concept'::public.curated_course_node_type, 'Sluglines, action lines, dialogue, and parentheticals', null, 0),
  ('61f37556-1662-4fb1-9c87-cf59575656d6', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'e6eaf9ee-30da-45f3-9e60-a4d21f74cc73', 'concept'::public.curated_course_node_type, 'Writing what can be seen and heard', null, 1),
  ('54d78556-4c09-4cc9-934f-1d266c895e51', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'e6eaf9ee-30da-45f3-9e60-a4d21f74cc73', 'concept'::public.curated_course_node_type, 'Compression, readability, and page economy', null, 2),
  ('f55fc102-5e4d-4ea9-b900-1a868fe8ecdf', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c27dd226-a151-451a-b2fb-10922b68f915', 'subtopic'::public.curated_course_node_type, 'Structure and Development Tools', 'Students use loglines, treatments, outlines, and beat sheets to test story logic before drafting.', 1),
  ('55e3fcf7-e48d-42e6-95b0-8f34617f6fd5', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f55fc102-5e4d-4ea9-b900-1a868fe8ecdf', 'concept'::public.curated_course_node_type, 'Logline, premise, and synopsis', null, 0),
  ('6b1427e1-a0ef-44db-981c-92ef6fa6658e', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f55fc102-5e4d-4ea9-b900-1a868fe8ecdf', 'concept'::public.curated_course_node_type, 'Three-act, sequence, and alternative structures', null, 1),
  ('7a5cd8f9-ac87-469d-91e5-f256be76d17d', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f55fc102-5e4d-4ea9-b900-1a868fe8ecdf', 'concept'::public.curated_course_node_type, 'Subplot, theme, and genre conventions', null, 2),
  ('c1bc126c-3370-4598-9306-6ea0d97a6fe1', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c27dd226-a151-451a-b2fb-10922b68f915', 'subtopic'::public.curated_course_node_type, 'Adaptation and Episodic Possibilities', 'This subtopic connects prose, stage, and screen by asking what changes when a story moves across media.', 2),
  ('a9d01859-959f-4ba0-9130-506e65ba3e20', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c1bc126c-3370-4598-9306-6ea0d97a6fe1', 'concept'::public.curated_course_node_type, 'Adapting character, scene, and point of view', null, 0),
  ('a29f8435-cf3b-4765-8a64-a5a6368a36e9', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c1bc126c-3370-4598-9306-6ea0d97a6fe1', 'concept'::public.curated_course_node_type, 'Short film versus feature versus episodic writing', null, 1),
  ('4d18b861-517a-433a-ae16-3c382b98ca94', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c1bc126c-3370-4598-9306-6ea0d97a6fe1', 'concept'::public.curated_course_node_type, 'Pitching, coverage, and revision notes', null, 2),
  ('f44dd60f-324c-4bad-b692-77146ede075a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Genre, Speculative Writing, and Hybrid Forms', 'A world-class creative writing course treats genre and hybridity as serious artistic tools: students explore literary fiction, speculative modes, crime, romance, horror, lyric essay, prose poetry, and digital forms.', 8),
  ('12c5823d-34c7-462e-9e84-dc8a4d730a74', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f44dd60f-324c-4bad-b692-77146ede075a', 'subtopic'::public.curated_course_node_type, 'Genre as Promise and Pressure', 'Students learn how genre creates expectations that writers can fulfill, bend, or break.', 0),
  ('2aeb9332-d0ae-40a0-b7d5-c6db7436fe59', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '12c5823d-34c7-462e-9e84-dc8a4d730a74', 'concept'::public.curated_course_node_type, 'Conventions, tropes, and reader contracts', null, 0),
  ('158641c2-f17c-45e3-9367-4d08d0d36244', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '12c5823d-34c7-462e-9e84-dc8a4d730a74', 'concept'::public.curated_course_node_type, 'Literary versus commercial category debates', null, 1),
  ('54c40ea9-8154-4fa2-9f91-993c468109ee', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '12c5823d-34c7-462e-9e84-dc8a4d730a74', 'concept'::public.curated_course_node_type, 'Worldbuilding, suspense, mystery, and revelation', null, 2),
  ('195ee624-0d9d-4860-8236-9a1bf230a925', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f44dd60f-324c-4bad-b692-77146ede075a', 'subtopic'::public.curated_course_node_type, 'Hybrid Forms', 'Hybrid work helps students cross boundaries between poetry, prose, essay, script, image, and document.', 1),
  ('db3b5413-483a-4246-9ef2-28d84d9ab2c0', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '195ee624-0d9d-4860-8236-9a1bf230a925', 'concept'::public.curated_course_node_type, 'Lyric essay and prose poetry', null, 0),
  ('ec6bd086-e8ad-4cbf-a374-d037d4f973d4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '195ee624-0d9d-4860-8236-9a1bf230a925', 'concept'::public.curated_course_node_type, 'Documentary collage and found text', null, 1),
  ('cd8c077d-1458-4129-81c1-9d839a3e4c84', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '195ee624-0d9d-4860-8236-9a1bf230a925', 'concept'::public.curated_course_node_type, 'Multimodal and digital experiments', null, 2),
  ('f0c6364b-b0c3-43f8-be98-4824e98b7f17', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f44dd60f-324c-4bad-b692-77146ede075a', 'subtopic'::public.curated_course_node_type, 'Experiment with Purpose', 'The course distinguishes productive formal risk from confusion for its own sake.', 2),
  ('8eadea2b-9128-4321-9fdc-ff57089de88a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f0c6364b-b0c3-43f8-be98-4824e98b7f17', 'concept'::public.curated_course_node_type, 'Constraint and procedural writing', null, 0),
  ('029c2de4-f496-4444-bda1-7d10bbef9342', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f0c6364b-b0c3-43f8-be98-4824e98b7f17', 'concept'::public.curated_course_node_type, 'Fragment, list, archive, and erasure', null, 1),
  ('389fa698-a345-4b73-96c8-c72cd6816255', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'f0c6364b-b0c3-43f8-be98-4824e98b7f17', 'concept'::public.curated_course_node_type, 'Reader orientation and interpretive payoff', null, 2),
  ('a7d9e760-38b1-4401-ba8e-27720afd919e', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Workshop Method, Critique Culture, and Revision', 'Workshop is the heart of the course, but it must be taught as an ethical, specific, inclusive, craft-centered practice rather than a casual opinion exchange.', 9),
  ('1e8ef6f5-7f5a-4d56-9892-e28939270159', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'a7d9e760-38b1-4401-ba8e-27720afd919e', 'subtopic'::public.curated_course_node_type, 'Giving Useful Feedback', 'Students practice feedback that is specific, text-based, generous, and oriented toward the writer''s project.', 0),
  ('ca225e55-96a2-4ced-88a6-b5728662ecd0', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '1e8ef6f5-7f5a-4d56-9892-e28939270159', 'concept'::public.curated_course_node_type, 'Descriptive versus prescriptive comments', null, 0);
