  ('a7cb59cb-9d7d-4f5a-8844-945be8a6f47c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '201fa0ea-6307-46d1-b1e6-afc43d976a56', 'concept'::public.curated_course_node_type, 'Choosing revision priorities', null, 2),
  ('67a7a140-531a-4639-a2f5-e973135ed25f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'a7d9e760-38b1-4401-ba8e-27720afd919e', 'subtopic'::public.curated_course_node_type, 'Revision as Re-Seeing', 'Revision is framed as structural reimagining, not just correction.', 2),
  ('c3f99449-4526-4179-9637-b49bf71ca9fb', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '67a7a140-531a-4639-a2f5-e973135ed25f', 'concept'::public.curated_course_node_type, 'Global, scene-level, paragraph, line, and copy edits', null, 0),
  ('0334eecf-9878-4fb8-84a4-4f368500880b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '67a7a140-531a-4639-a2f5-e973135ed25f', 'concept'::public.curated_course_node_type, 'Cutting, expanding, reordering, and changing point of view', null, 1),
  ('b879f830-7c46-4d0d-af2f-a87ed13272ed', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '67a7a140-531a-4639-a2f5-e973135ed25f', 'concept'::public.curated_course_node_type, 'Revision memos and before/after reflection', null, 2),
  ('10a4d2a8-0203-479b-b57f-21c2bcbc5116', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Style, Rhetoric, Editing, and Sentence Craft', 'This module gives students control at the sentence and paragraph level: clarity, rhythm, emphasis, diction, grammar, rhetorical situation, and final polish.', 10),
  ('0e404aa6-200a-4097-afcf-8166f849e2f3', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '10a4d2a8-0203-479b-b57f-21c2bcbc5116', 'subtopic'::public.curated_course_node_type, 'Sentence Rhythm and Clarity', 'Students learn how syntax shapes pace, tone, and attention.', 0),
  ('c1bb37a2-2648-4bbb-9c65-0622fb3f9bf3', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0e404aa6-200a-4097-afcf-8166f849e2f3', 'concept'::public.curated_course_node_type, 'Coordination, subordination, and sentence variety', null, 0),
  ('90c3fb2c-46b8-4424-b37c-549d1cd5e41b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0e404aa6-200a-4097-afcf-8166f849e2f3', 'concept'::public.curated_course_node_type, 'Cohesion, emphasis, and paragraph movement', null, 1),
  ('3c887a69-b6fa-403b-960b-70526b7effb0', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0e404aa6-200a-4097-afcf-8166f849e2f3', 'concept'::public.curated_course_node_type, 'Concision without flattening voice', null, 2),
  ('ce9fd63f-ddcd-4708-a37e-a3c8bb1ce334', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '10a4d2a8-0203-479b-b57f-21c2bcbc5116', 'subtopic'::public.curated_course_node_type, 'Rhetorical Situation and Audience', 'Creative writing still has audience, purpose, context, and genre conventions.', 1),
  ('bcc561d3-17e6-41a8-9dfe-bb940c5992f4', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'ce9fd63f-ddcd-4708-a37e-a3c8bb1ce334', 'concept'::public.curated_course_node_type, 'Audience awareness without pandering', null, 0),
  ('70d19fcf-c2a0-4154-8f40-3bedae3c70c5', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'ce9fd63f-ddcd-4708-a37e-a3c8bb1ce334', 'concept'::public.curated_course_node_type, 'Genre-specific expectations', null, 1),
  ('5732b66c-1510-4e25-861a-296fa15c90d1', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'ce9fd63f-ddcd-4708-a37e-a3c8bb1ce334', 'concept'::public.curated_course_node_type, 'Voice, register, and rhetorical stance', null, 2),
  ('eb729438-e0ad-4637-9551-9e00848b7057', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '10a4d2a8-0203-479b-b57f-21c2bcbc5116', 'subtopic'::public.curated_course_node_type, 'Editing and Proofreading', 'Students distinguish developmental revision from line editing and final copyediting.', 2),
  ('b3b57087-6b08-4cf4-b0b1-282307015265', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'eb729438-e0ad-4637-9551-9e00848b7057', 'concept'::public.curated_course_node_type, 'Style sheets and consistency', null, 0),
  ('45f50e0d-ed60-40c2-8a3d-7ead979e8c12', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'eb729438-e0ad-4637-9551-9e00848b7057', 'concept'::public.curated_course_node_type, 'Grammar, punctuation, and usage choices', null, 1),
  ('573545d1-4f77-4315-b6c9-8ce7632e9953', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'eb729438-e0ad-4637-9551-9e00848b7057', 'concept'::public.curated_course_node_type, 'Final manuscript formatting and proofreading workflow', null, 2),
  ('dd65480a-9af7-4d8d-be10-449645310394', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Research, Ethics, Representation, and World Knowledge', 'Students learn to write beyond themselves responsibly: research, listening, consent, cultural context, power, and ethics all shape credible and careful creative work.', 11),
  ('e9052ab0-2277-474d-9e39-0196f0565f0a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'dd65480a-9af7-4d8d-be10-449645310394', 'subtopic'::public.curated_course_node_type, 'Research for Imaginative Writing', 'Research gives specificity, complexity, and accountability to invented and nonfiction worlds.', 0),
  ('39e05ea6-bed9-4bd3-bf88-0387eb35727b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'e9052ab0-2277-474d-9e39-0196f0565f0a', 'concept'::public.curated_course_node_type, 'Field observation and interviews', null, 0),
  ('6d8efcc2-2e50-451e-ae8e-005e3be0878d', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'e9052ab0-2277-474d-9e39-0196f0565f0a', 'concept'::public.curated_course_node_type, 'Archives, maps, photographs, and public records', null, 1),
  ('b64295eb-fa0b-4fd5-9464-2bb709b17157', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'e9052ab0-2277-474d-9e39-0196f0565f0a', 'concept'::public.curated_course_node_type, 'Specialized vocabularies and material culture', null, 2),
  ('b8671789-a92a-47e8-ab05-45f7634d026f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'dd65480a-9af7-4d8d-be10-449645310394', 'subtopic'::public.curated_course_node_type, 'Ethics of Representation', 'Students consider the risks of appropriating, simplifying, or exploiting lives and communities.', 1),
  ('4f654984-b324-413f-985b-0a9ca72394b7', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'b8671789-a92a-47e8-ab05-45f7634d026f', 'concept'::public.curated_course_node_type, 'Writing across difference', null, 0),
  ('602798a5-4268-48d2-8281-a15b1b833b70', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'b8671789-a92a-47e8-ab05-45f7634d026f', 'concept'::public.curated_course_node_type, 'Consent, privacy, and vulnerable subjects', null, 1),
  ('e1f72bb0-e5f3-4eb8-9de3-1c689090e47f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'b8671789-a92a-47e8-ab05-45f7634d026f', 'concept'::public.curated_course_node_type, 'Stereotype, power, and narrative responsibility', null, 2),
  ('6e734ad4-cbd5-43a5-8b2a-84fbfd05c747', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'dd65480a-9af7-4d8d-be10-449645310394', 'subtopic'::public.curated_course_node_type, 'Context and Credibility', 'The goal is to make worlds feel lived in without turning drafts into exposition dumps.', 2),
  ('675faa66-946e-40d8-80f6-c44005fc5537', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6e734ad4-cbd5-43a5-8b2a-84fbfd05c747', 'concept'::public.curated_course_node_type, 'Selective detail and earned authority', null, 0),
  ('f168e2f0-a828-4193-80e9-8edc8ee1b389', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6e734ad4-cbd5-43a5-8b2a-84fbfd05c747', 'concept'::public.curated_course_node_type, 'Fact-checking and plausibility', null, 1),
  ('685e8f41-2185-4214-8f6a-eda6f380c84f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6e734ad4-cbd5-43a5-8b2a-84fbfd05c747', 'concept'::public.curated_course_node_type, 'Balancing research with story momentum', null, 2),
  ('0b123a97-57a0-4846-84a8-7627af919416', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Publication, Literary Citizenship, and Professional Practice', 'Students learn how writing circulates: literary magazines, readings, contests, agents, presses, workshops, grants, residencies, online presence, and sustainable creative lives.', 12),
  ('1efea06f-d23d-4f25-aef2-caaa9c6edaa8', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0b123a97-57a0-4846-84a8-7627af919416', 'subtopic'::public.curated_course_node_type, 'Submission and Publication Basics', 'Students learn the practical mechanics of sharing work professionally.', 0),
  ('76d5422b-095d-452a-829e-6fc398b27115', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '1efea06f-d23d-4f25-aef2-caaa9c6edaa8', 'concept'::public.curated_course_node_type, 'Cover letters, bios, and submission trackers', null, 0),
  ('eb224b4e-6d89-46c7-8865-1cd5da9d3d23', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '1efea06f-d23d-4f25-aef2-caaa9c6edaa8', 'concept'::public.curated_course_node_type, 'Literary magazines, contests, presses, and Submittable', null, 1);
