  ('7339d855-cc43-4f6d-b2dc-dc541062bc4c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0b123a97-57a0-4846-84a8-7627af919416', 'subtopic'::public.curated_course_node_type, 'Literary Citizenship', 'Writers join communities by reading, attending, responding, reviewing, volunteering, and supporting other writers.', 1),
  ('3a69a205-978b-4795-9244-3799b83ba161', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7339d855-cc43-4f6d-b2dc-dc541062bc4c', 'concept'::public.curated_course_node_type, 'Reading series, journals, and local literary ecosystems', null, 0),
  ('1824a1af-7fe7-47b0-81cd-4e30f2602659', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7339d855-cc43-4f6d-b2dc-dc541062bc4c', 'concept'::public.curated_course_node_type, 'Book reviewing and interview practice', null, 1),
  ('ac39150c-157b-48dd-a2f3-42c61fe9a917', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '7339d855-cc43-4f6d-b2dc-dc541062bc4c', 'concept'::public.curated_course_node_type, 'Community agreements and professional generosity', null, 2),
  ('c65a3bed-93fa-4210-8d56-97c4c3d57c2a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0b123a97-57a0-4846-84a8-7627af919416', 'subtopic'::public.curated_course_node_type, 'Career Sustainability', 'Students plan realistic next steps without reducing art to a marketplace.', 2),
  ('0a79a839-d1a1-401d-acb7-9e1c88aac0ba', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c65a3bed-93fa-4210-8d56-97c4c3d57c2a', 'concept'::public.curated_course_node_type, 'MFA, workshops, residencies, and independent study', null, 0),
  ('a21646d1-f8d0-4831-8c2c-c7789617f55e', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c65a3bed-93fa-4210-8d56-97c4c3d57c2a', 'concept'::public.curated_course_node_type, 'Grants, fellowships, and artist statements', null, 1),
  ('af6b02df-b3bf-449d-acf9-bf1fe6e877b0', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'c65a3bed-93fa-4210-8d56-97c4c3d57c2a', 'concept'::public.curated_course_node_type, 'Portfolio, website, and long-term writing goals', null, 2),
  ('6b018775-3a50-4c83-9cf5-4deace9b7a0c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Performance, Reading Aloud, and Public Presentation', 'Reading aloud makes writers hear rhythm, pacing, audience response, breath, emphasis, and the performative life of language.', 13),
  ('079aa057-64e0-4a3a-a356-bf7d14b4a79a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6b018775-3a50-4c83-9cf5-4deace9b7a0c', 'subtopic'::public.curated_course_node_type, 'Voice on the Page and in the Room', 'Students discover what their sentences and lines do when embodied through breath and sound.', 0),
  ('e56d9a50-6a8a-4e14-886c-58bae10d2eca', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '079aa057-64e0-4a3a-a356-bf7d14b4a79a', 'concept'::public.curated_course_node_type, 'Pacing, pause, emphasis, and clarity', null, 0),
  ('b9823676-163c-4e0e-bbff-ac9bfe1e912d', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '079aa057-64e0-4a3a-a356-bf7d14b4a79a', 'concept'::public.curated_course_node_type, 'Poetry, prose, and dramatic reading differences', null, 1),
  ('9552d83a-b668-4b5d-bc15-7f5e98d1832c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '079aa057-64e0-4a3a-a356-bf7d14b4a79a', 'concept'::public.curated_course_node_type, 'Microphone, stage presence, and audience contact', null, 2),
  ('99c92057-6a80-4eff-babe-57a16db79bcb', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6b018775-3a50-4c83-9cf5-4deace9b7a0c', 'subtopic'::public.curated_course_node_type, 'Revision by Ear', 'Reading aloud becomes a revision tool for identifying slackness, confusion, excess, and missed energy.', 1),
  ('3ff32b61-d101-4e0f-bc31-0a2aef01150a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '99c92057-6a80-4eff-babe-57a16db79bcb', 'concept'::public.curated_course_node_type, 'Sound edits and rhythm adjustments', null, 0),
  ('e37c2fd3-6303-4a9e-8696-e4934009ad10', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '99c92057-6a80-4eff-babe-57a16db79bcb', 'concept'::public.curated_course_node_type, 'Dialogue testing and scene energy', null, 1),
  ('f37faa5a-8a44-44e0-99c2-4056adbe0645', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '99c92057-6a80-4eff-babe-57a16db79bcb', 'concept'::public.curated_course_node_type, 'Cutting or expanding for live delivery', null, 2),
  ('b05c3ab2-8ef4-4d40-9752-d48942da808c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '6b018775-3a50-4c83-9cf5-4deace9b7a0c', 'subtopic'::public.curated_course_node_type, 'Public Literary Presentation', 'Students practice sharing work professionally and thoughtfully.', 2),
  ('84d32c68-36c9-400e-ae7e-3af4b7121a81', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'b05c3ab2-8ef4-4d40-9752-d48942da808c', 'concept'::public.curated_course_node_type, 'Reading selection and time limits', null, 0),
  ('2b895a20-0b59-4e0a-8819-be8fb7cf1d4c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'b05c3ab2-8ef4-4d40-9752-d48942da808c', 'concept'::public.curated_course_node_type, 'Introductions and contextual framing', null, 1),
  ('45eda7dd-9ac2-46d8-86a2-3217631969cc', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'b05c3ab2-8ef4-4d40-9752-d48942da808c', 'concept'::public.curated_course_node_type, 'Q&A, feedback, and event etiquette', null, 2),
  ('0a05d9eb-57ce-4920-a8cf-73a254136e8b', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', null, 'topic'::public.curated_course_node_type, 'Capstone Portfolio: Original Body of Work and Artist Statement', 'The capstone synthesizes the course: students revise a substantial portfolio, frame their artistic aims, document their process, and present work publicly or professionally.', 14),
  ('9c002de0-e087-4ac8-aac9-7df90c7ce006', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0a05d9eb-57ce-4920-a8cf-73a254136e8b', 'subtopic'::public.curated_course_node_type, 'Portfolio Architecture', 'Students learn to curate a coherent body of work rather than simply collect assignments.', 0),
  ('d8575e1e-4f3e-4285-8966-f0e8df8d209f', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '9c002de0-e087-4ac8-aac9-7df90c7ce006', 'concept'::public.curated_course_node_type, 'Selecting strongest pieces', null, 0),
  ('441c2d0e-473b-4093-9e21-1bde0925dc7c', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '9c002de0-e087-4ac8-aac9-7df90c7ce006', 'concept'::public.curated_course_node_type, 'Ordering, pacing, and genre balance', null, 1),
  ('9edbdafc-8981-474b-af3f-9f6b3710fb91', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '9c002de0-e087-4ac8-aac9-7df90c7ce006', 'concept'::public.curated_course_node_type, 'Table of contents and project rationale', null, 2),
  ('ab5d2690-4527-4fee-8150-c13416115a78', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', '0a05d9eb-57ce-4920-a8cf-73a254136e8b', 'subtopic'::public.curated_course_node_type, 'Artist Statement and Reflection', 'The statement helps students articulate what their work is trying to do and how it has changed through revision.', 1),
  ('b53d9043-aa07-400f-ba90-dd31c9ff0a3a', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'ab5d2690-4527-4fee-8150-c13416115a78', 'concept'::public.curated_course_node_type, 'Influences, questions, themes, and craft aims', null, 0),
  ('e95af850-8b1a-49fc-a9a4-90ffe62e6914', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'ab5d2690-4527-4fee-8150-c13416115a78', 'concept'::public.curated_course_node_type, 'Process account and revision evidence', null, 1),
  ('883b2e31-3bd2-428c-9e61-e183ba4c0757', 'b6c7d8e9-0f1a-4c35-8e45-5f6a7b8c9d55', 'ab5d2690-4527-4fee-8150-c13416115a78', 'concept'::public.curated_course_node_type, 'Audience, ethics, and future direction', null, 2),
